  async completePostCtcTask({employee,taskId,expectedType,action,next,at=new Date().toISOString()}){
    const client=await this.pool.connect();
    try{
      await client.query('begin');
      const task=await this.authorizedWorkflowTask(client,employee,taskId);
      if(task.task_type!==expectedType)throw new Error(`${action} is not valid for this task`);
      const completed=await client.query("update workflow_tasks set state='completed',completed_at=$2,updated_at=now() where id=$1 and state not in ('completed','cancelled','not_applicable') returning id",[taskId,at]);
      if(completed.rowCount){
        await this.addWorkflowHistory(client,taskId,{at,action,fromState:task.state,toState:'completed',actorEmail:employee.email,metadata:{}});
        await this.createPostCtcTask(client,task,{...next,at});
      }
      await client.query('commit');return {ok:true};
    }catch(error){await client.query('rollback');throw error;}finally{client.release();}
  }
